   138|/**
   139| * Detect a vague execution request on public chat — one that has an execution
   140| * verb (fix, deploy, etc.) but no concrete target, error, file, or context.
   141| * Instead of returning a canned auth wall, these should route to the LLM for
   142| * a helpful diagnostic response ("What problem are you seeing?").
   143| */
   144|export function isVagueExecutionRequest(message: string): boolean {
   145|  const text = (message ?? '').toLowerCase().trim();
   146|  if (!text || text.length > 500) return false;
   147|
   148|  // Must contain an execution verb
   149|  const hasExecVerb = /\b(?:fix|deploy|patch|commit|push|build|ship|rollback|release|implement|create|update|remove|delete|run)\b/.test(text);
   150|  if (!hasExecVerb) return false;
   151|
   152|  // If there's a concrete target (file name, endpoint, specific bug description,
   153|  // error message, stack trace, SHA), it's NOT vague — block normally.
   154|  const hasConcreteTarget = /\b(?:file|endpoint|route|module|service|component|function|handler|test|bug\s+(?:in|on|at|with)|error[:\s]|stack\s+trace|exception|crash|fail(?:ed|ure)|sha|commit\s+[a-f0-9]|render|supabase|github|database|table|column|500|502|503|timeout|cors|ssl|dns|auth(?:entication|orized)|401|403|404|env\s+var|config)\b/.test(text);
   155|  if (hasConcreteTarget) return false;
   156|
   157|  // Vague patterns: "fix the production problem", "deploy this", "fix it",
   158|  // "build the feature", with no specifics.
   159|  const vaguePatterns = [
   160|    /\bfix\s+(?:the\s+)?(?:production\s+)?(?:problem|issue|bug|error|thing|it|this|that)\b/i,
   161|    /\bdeploy\s+(?:this|that|it|now|live)\b/i,
   162|    /\bpatch\s+(?:this|that|it|the\s+issue)\b/i,
   163|    /\bbuild\s+(?:the\s+)?(?:feature|app|service|module|thing)\b/i,
   164|    /\bimplement\s+(?:this|that|the\s+feature|it)\b/i,
   165|    /\bcreate\s+(?:this|that|it|the\s+module)\b/i,
   166|    /\brollback\s+(?:production|the\s+deploy|it)\b/i,
   167|    /\brun\s+(?:the\s+)?(?:tests|qa|checks|validation)\b/i,
   168|  ];
   169|  return vaguePatterns.some((p) => p.test(text));
