   240|export function buildFallbackAnswer(message: string): string {
   241|  const normalized = message.toLowerCase();
   242|
   243|  // ── Vague action requests (TJ-03): ask for specifics instead of flat refusal ──
   244|  if (/\bfix\b.*\bproblem\b|\bfix\b.*\bproduction\b|\bfix\b.*\bissue\b|\bdeploy\b.*\bnow\b|\bship\b.*\bnow\b/.test(normalized)) {
   245|    return 'I can help with that. To take action on production, I need more specifics: (1) What exactly is broken or what needs to change? (2) When did it start? (3) What error messages or symptoms are you seeing? (4) Is this a code fix, a config change, or a deployment? Once you provide those details, I can either guide you through the fix or execute it with owner approval.';
   246|  }
   247|
   248|  // ── A/B test rollout assumption (CA-02): challenge the assumption ──
   249|  if (/a\/b\s*test|variant\s+b\s+won|roll\s*out.*everyone|roll\s*out.*immediately/.test(normalized)) {
   250|    return 'Before rolling out variant B to everyone, consider these risks: (1) Statistical significance — was the sample size large enough? A 95% confidence interval should be confirmed. (2) Segment effects — variant B may have won overall but lost in key segments (mobile vs desktop, new vs returning users). (3) Duration — was the test long enough to account for day-of-week or seasonality effects? (4) Novelty effect — early wins from a change can fade once users adapt. (5) Guardrail metrics — did variant B harm secondary metrics like latency, error rate, or churn? Recommend: segment the results, check guardrails, and consider a gradual rollout (10% → 50% → 100%) rather than an immediate full rollout.';
   251|  }
   252|
   253|  // ── HTTP 200 assumption (CA-01): challenge the assumption ──
   254|  if (/http\s*200.*transaction.*worked|200.*correctly.*confirm/.test(normalized)) {
   255|    return 'HTTP 200 only confirms the server accepted the request — it does NOT mean the entire transaction worked correctly. To verify end-to-end: (1) Check the response body for business-level errors (e.g., partial_success, queued, or error codes inside a 200 response). (2) Confirm downstream effects — did the database write commit? Did the payment actually settle? (3) Check idempotency — was the transaction duplicated? (4) Verify with a read-back query or webhook confirmation. A 200 is necessary but not sufficient for transaction success.';
   256|  }
   257|
   258|  // ── Vague strategy requests (FU-01/02/03/04): ask clarifying questions ──
   259|  if (/expansion\s*strategy|build.*strategy|what.*prioritize|double\s*down|buy\s*or\s*build/.test(normalized)) {
   260|    return 'To give you a specific, actionable recommendation rather than a generic framework, I need a few clarifying details: (1) What is your current market position and who are your top 3 competitors? (2) What is your growth constraint right now — is it demand (not enough leads), supply (can\'t deliver fast enough), or retention (churning too fast)? (3) What is your budget and timeline for this initiative? (4) What has already been tried and what were the results? With those answers, I can give you a prioritized plan with expected ROI for each option instead of a one-size-fits-all answer.';
   261|  }
   262|
   263|  if (normalized.includes('api') || normalized.includes('backend') || normalized.includes('health')) {
   264|    return 'The app frontend is intended to run on chat.ivxholding.com and the API on api.ivxholding.com. If live replies fail, confirm DNS first, then check GET /health and POST /public/chat on the API host.';
   265|  }
   266|
   267|  if (normalized.includes('invest') || normalized.includes('real estate') || normalized.includes('property')) {
   268|    return 'IVX is designed to make real-estate participation easier to understand. A good beginner flow is: learn the deal, review the timeline and return assumptions, understand the risks, then only invest after reading the actual documents.';
   269|  }
   270|
   271|  if (normalized.includes('login') || normalized.includes('sign up') || normalized.includes('account')) {
   272|    return 'For account issues, keep the flow simple: sign up, verify your email, complete profile steps, then continue into the app. If a real account or verification issue is blocking progress, route it to human support.';
