   293|  if (!isPublicChatAIConfigured() || !endpoint) {
   294|    throw new Error('IVX AI proxy configuration is missing.');
   295|  }
   296|
   297|  const promptParts = [
   298|    'Recent public chat transcript:',
   299|    buildTranscript(input.history),
